    if (parts.length >= 3) {
        const a = parseInt(parts[0], 10);
        const b = parseInt(parts[1], 10);
        const c = parseInt(parts[2], 10);
        const max = a > b ? (a > c ? a : c) : (b > c ? b : c);
        console.log(max);
    }
}

main();

